IF COL_LENGTH('PlanoContas','Natureza') IS NULL ALTER TABLE PlanoContas ADD Natureza nvarchar(20) NOT NULL CONSTRAINT DF_PlanoContas_Natureza DEFAULT 'Devedora';
IF COL_LENGTH('PlanoContas','AceitaLancamentos') IS NULL ALTER TABLE PlanoContas ADD AceitaLancamentos bit NOT NULL CONSTRAINT DF_PlanoContas_AceitaLancamentos DEFAULT 1;
IF COL_LENGTH('PlanoContas','CentroCustoObrigatorio') IS NULL ALTER TABLE PlanoContas ADD CentroCustoObrigatorio bit NOT NULL CONSTRAINT DF_PlanoContas_CentroCustoObrigatorio DEFAULT 0;
IF OBJECT_ID('LancamentosContabeis','U') IS NULL BEGIN
CREATE TABLE LancamentosContabeis(Id int IDENTITY PRIMARY KEY,EmpresaId int NOT NULL,DataLancamento datetime2 NOT NULL,Numero nvarchar(30) NOT NULL,Descricao nvarchar(250) NOT NULL,DocumentoReferencia nvarchar(80) NULL,OrigemModulo nvarchar(50) NULL,Estado nvarchar(30) NOT NULL,DataContabilizacao datetime2 NULL,UtilizadorId int NULL,DataCriacao datetime2 NOT NULL,DataAtualizacao datetime2 NULL,Ativo bit NOT NULL,CONSTRAINT FK_LC_Empresa FOREIGN KEY(EmpresaId) REFERENCES Empresas(Id),CONSTRAINT FK_LC_Utilizador FOREIGN KEY(UtilizadorId) REFERENCES Utilizadores(Id));
CREATE UNIQUE INDEX IX_LancamentosContabeis_Empresa_Numero ON LancamentosContabeis(EmpresaId,Numero); END;
IF OBJECT_ID('LancamentoContabilLinhas','U') IS NULL BEGIN
CREATE TABLE LancamentoContabilLinhas(Id int IDENTITY PRIMARY KEY,LancamentoContabilId int NOT NULL,PlanoContasId int NOT NULL,Descricao nvarchar(250) NULL,Debito decimal(18,2) NOT NULL,Credito decimal(18,2) NOT NULL,CentroCusto nvarchar(80) NULL,DataCriacao datetime2 NOT NULL,DataAtualizacao datetime2 NULL,Ativo bit NOT NULL,CONSTRAINT FK_LCL_Lancamento FOREIGN KEY(LancamentoContabilId) REFERENCES LancamentosContabeis(Id) ON DELETE CASCADE,CONSTRAINT FK_LCL_Plano FOREIGN KEY(PlanoContasId) REFERENCES PlanoContas(Id)); END;
